#!/usr/bin/env bash
# Regenerate the shell's lexer and parser from edc_lex.l / edc_parse.y, or verify that
# the committed copies are current.
#
#   tools/regen_grammar.sh           # regenerate and write into src/shell/
#   tools/regen_grammar.sh --check   # verify they are current (exit 1 if not)
#
# WHY THE GENERATED FILES ARE COMMITTED
#
# The grammar used to be generated by genrules on every build, which made flex and bison
# build-host requirements: macOS ships a bison from 2006 that cannot parse `%define
# api.value.type`, Git for Windows ships neither tool, and every CI job had to install them
# (brew kegs on PATH by hand, MSYS2 pacman on Windows). The failure mode was a build that
# broke on a machine where "nothing changed".
#
# So the generated files are checked in and compiled directly. That moves the risk from
# "the build depends on which flex/bison this machine has" to "somebody edited the grammar
# and forgot to regenerate", which this script and its --check mode are here to close:
# CI runs --check, so forgetting fails the build instead of silently shipping the old
# grammar.
#
# DETERMINISM
#
# Cross-machine comparison only works if generation is reproducible, so:
#   - the files are generated in a scratch dir under their bare names, which makes the
#     `#line` directives relative ("edc_parse.y") rather than absolute paths;
#   - the tool versions are pinned below and a mismatch is refused, not tolerated;
#   - bison stamps its own version into line 1 of the output, which would make every
#     patch release of bison produce a diff, so that one line is normalised. Everything
#     else in the output is kept byte for byte, so a real skeleton change still shows up.
#
# Verified when this was introduced: two runs on the same machine are byte-identical, the
# output contains no absolute paths, timestamps or user names, flex embeds no version, and
# bison's version appears on line 1 only.

set -euo pipefail

# Major.minor only: a patch bump of either tool should not force a regeneration, and the
# normalisation above keeps bison's version out of the compared bytes.
BISON_REQUIRED="3.8"
FLEX_REQUIRED="2.6"

REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
SRC_DIR="$REPO_ROOT/src/shell"

# Outputs as they are compiled. Keep in sync with src/shell/BUILD.
OUTPUTS=(edc_lex.c edc_parse.tab.c edc_parse.tab.h)

check=false
case "${1:-}" in
    --check) check=true ;;
    "") ;;
    *)
        echo "usage: $0 [--check]" >&2
        exit 2
        ;;
esac

die() { echo "error: $*" >&2; exit 1; }

command -v flex >/dev/null 2>&1 || die "flex not found on PATH" \
    "(Linux: apt-get install flex; macOS: brew install flex; Windows: MSYS2 pacman -S flex m4)"
command -v bison >/dev/null 2>&1 || die "bison not found on PATH" \
    "(Linux: apt-get install bison; macOS: brew install bison; Windows: MSYS2 pacman -S bison)"

# Version gate. The grammar needs bison 3.0+ for -Werror=conflicts-* and %define
# api.value.type, but the committed output came from 3.8 and a different major.minor can
# emit a different skeleton -- which would show up as a whole-file diff rather than a
# useful one. Refuse instead of producing a confusing result.
BISON_VERSION=$(bison --version | head -n1 | sed -n 's/.*) \([0-9][0-9.]*\).*/\1/p')
FLEX_VERSION=$(flex --version | head -n1 | sed -n 's/[^0-9]*\([0-9][0-9.]*\).*/\1/p')
BISON_MM=$(echo "$BISON_VERSION" | cut -d. -f1,2)
FLEX_MM=$(echo "$FLEX_VERSION" | cut -d. -f1,2)

if [[ "$BISON_MM" != "$BISON_REQUIRED" ]]; then
    die "bison $BISON_VERSION found, $BISON_REQUIRED.x required.
This pins the generator so the committed output stays comparable. If you mean to move the
baseline, change BISON_REQUIRED here, regenerate, and commit the result in the same commit."
fi
if [[ "$FLEX_MM" != "$FLEX_REQUIRED" ]]; then
    die "flex $FLEX_VERSION found, $FLEX_REQUIRED.x required.
Same reasoning as bison; see BISON_REQUIRED above."
fi

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

# Bare names, so the generated #line directives stay relative. src/shell/ is where the
# outputs live and where the .l/.y already are, so the compiler resolves them correctly.
cp "$SRC_DIR/edc_lex.l" "$SRC_DIR/edc_parse.y" "$work/"

(
    cd "$work"
    # Same flags as the old genrule -- -Werror=conflicts-* is what makes an ambiguous rule
    # a build failure rather than a surprise at runtime, so it must stay here now that
    # generation is no longer part of every build.
    flex -o edc_lex.c edc_lex.l
    bison --defines=edc_parse.tab.h -o edc_parse.tab.c \
        -Werror=conflicts-sr -Werror=conflicts-rr edc_parse.y
)

# bison stamps "made by GNU Bison 3.8.2" into line 1. Normalise it so a patch release does
# not churn the committed file; nothing else in the output carries a version.
sed -i '1s|^/\* A Bison parser, made by GNU Bison .*|/* A Bison parser (generator version banner normalised -- see tools/regen_grammar.sh).  */|' \
    "$work/edc_parse.tab.c"

# Fail loudly rather than checking in something machine-specific.
for f in "${OUTPUTS[@]}"; do
    if grep -qE '/tmp/|/home/|/usr/|/Users/|\\Users\\|/build/' "$work/$f"; then
        die "$f contains an absolute path; the generator was invoked from a location that
leaked into a #line directive. Output must be reproducible across machines."
    fi
done

if $check; then
    stale=()
    for f in "${OUTPUTS[@]}"; do
        if ! cmp -s "$work/$f" "$SRC_DIR/$f"; then
            stale+=("$f")
        fi
    done
    if (( ${#stale[@]} )); then
        echo "error: the committed grammar output does not match edc_lex.l / edc_parse.y:" >&2
        for f in "${stale[@]}"; do
            echo "  src/shell/$f is stale" >&2
            diff -u "$SRC_DIR/$f" "$work/$f" | head -40 >&2 || true
        done
        echo >&2
        echo "This means either the grammar changed without regenerating, or it was" >&2
        echo "regenerated without committing the result. Fix it with:" >&2
        echo >&2
        echo "    tools/regen_grammar.sh && git add src/shell/${stale[0]}" >&2
        echo >&2
        exit 1
    fi
    echo "grammar output is current (bison $BISON_VERSION, flex $FLEX_VERSION)"
    exit 0
fi

changed=0
for f in "${OUTPUTS[@]}"; do
    if cmp -s "$work/$f" "$SRC_DIR/$f"; then
        echo "unchanged: src/shell/$f"
    else
        cp "$work/$f" "$SRC_DIR/$f"
        echo "updated:   src/shell/$f"
        changed=1
    fi
done

if (( changed )); then
    echo
    echo "Remember to commit the regenerated files with the grammar change."
fi
echo "generated with bison $BISON_VERSION, flex $FLEX_VERSION"
